// Package chart guards the hand-edits in dist/chart/templates/ that
// "kubebuilder edit --plugins=helm/v2-alpha" cannot regenerate on its own.
// Regenerating the chart reverts those edits with no other CI signal: the
// chart workflow only runs "helm lint" and a deploy, neither of which sends
// an admission request. This test renders the chart with "helm template"
// (no cluster needed) and checks the invariants the edits encode.
package chart

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"slices"
	"strconv"
	"strings"
	"testing"

	k8syaml "k8s.io/apimachinery/pkg/util/yaml"
)

const (
	opCreate = "CREATE"
	opUpdate = "UPDATE"
	opDelete = "DELETE"
)

// crdSourceDir is config/crd/bases, the controller-gen output dist/chart's
// CRD templates are generated from (CONTRIBUTING.md's chart warning).
const crdSourceDir = "../../config/crd/bases"

// ichorUIConfigRolePath is config/rbac/ichor-ui/role.yaml, generated by "make
// manifests-ichor-ui" from internal/uiapi/rbac_markers.go. Unlike the CRDs
// checkCRDsMatchConfig guards, this can't be propagated byte-for-byte into dist/chart --
// the chart's copy carries Helm template syntax (labels, {{ .Release }}) -- so
// checkUIBackendRBACMatchesConfig compares the two as rule sets instead.
const ichorUIConfigRolePath = "../../config/rbac/ichor-ui/role.yaml"

// controllerConfigRolePath is config/rbac/role.yaml, controller-gen's output from the
// controller's +kubebuilder:rbac markers: a ClusterRole and a namespaced Role, both named
// manager-role. Like ichorUIConfigRolePath it can't be copied into dist/chart, so
// checkControllerRBACMatchesConfig compares rule sets.
const controllerConfigRolePath = "../../config/rbac/role.yaml"

const (
	kindService                        = "Service"
	kindSecret                         = "Secret"
	kindConfigMap                      = "ConfigMap"
	kindServiceAccount                 = "ServiceAccount"
	kindRole                           = "Role"
	kindRoleBinding                    = "RoleBinding"
	kindClusterRole                    = "ClusterRole"
	kindClusterRoleBinding             = "ClusterRoleBinding"
	kindDeployment                     = "Deployment"
	kindValidatingWebhookConfiguration = "ValidatingWebhookConfiguration"
	kindCustomResourceDefinition       = "CustomResourceDefinition"
	kindValidatingAdmissionPolicy      = "ValidatingAdmissionPolicy"
	kindValidatingAdmissionPolicyBind  = "ValidatingAdmissionPolicyBinding"
)

const (
	webhookServiceName = "ichor-webhook-service"
	webhookConfigName  = "ichor-validating-webhook-configuration"
	certSecretName     = "ichor-webhook-server-cert"

	kubeProxySwitchPolicyName  = "ichor-cni-kubeproxy-switch"
	kubeProxySwitchBindingName = "ichor-cni-kubeproxy-switch-binding"

	// ichor-ui's own RBAC: fixed names, mirroring
	// config/rbac/ichor-ui/, unlike the controller's own release-templated ones.
	ichorUIServiceAccountName = "ichor-ui"
	ichorUIRoleName           = "ichor-ui-role"
	ichorUIRoleBindingName    = "ichor-ui-rolebinding"
	ichorUIDeploymentName     = "ichor-ui"

	// ichorUISecretsRoleName is the chart's own name for the namespaced Role carrying
	// the secrets rule (dist/chart/templates/rbac/ichor-ui-secrets-role.yaml): split into
	// its own file for packaging reasons that file's comment explains, so it doesn't share
	// config/rbac/ichor-ui/role.yaml's namespaced Role name (also "ichor-ui-role", there
	// disambiguated only by kind). checkUIBackendRBACMatchesConfig matches the two by rule
	// content, not by this name.
	ichorUISecretsRoleName = "ichor-ui-secrets-role"
)

// TestChartInvariants renders the committed chart under both the
// conventional release name (Makefile's HELM_RELEASE) and a non-default one,
// and checks every invariant the hand-edits in templates/ exist to hold.
func TestChartInvariants(t *testing.T) {
	for _, release := range []string{"ichor", "something-else"} {
		t.Run(release, func(t *testing.T) {
			docs := renderChart(t, release)
			checkFixedNames(t, release, docs)
			checkWebhookInvariants(t, release, docs)
			checkNoCABundle(t, release, docs)
			checkCertSecretHasNoData(t, release, docs)
			checkSecretsRoleAndBinding(t, release, docs)
			checkNoClusterWideSecretsRead(t, release, docs)
			checkCRDsMatchConfig(t, release, docs)
			checkKubeProxySwitchPolicy(t, release, docs)
			checkUIBackendRBACIsSeparate(t, release, docs)
			checkUIBackendRBACMatchesConfig(t, release, docs, false)
			checkControllerRBACMatchesConfig(t, release, docs)
			checkMonitoringOptionsOffByDefault(t, release, docs)
		})
	}
}

// ichorUIMetricsMonitorName is templates/prometheus/ichor-ui-metrics-monitor.yaml's
// fixed name, mirroring ichorUIServiceAccountName's own fixed-not-templated
// reasoning: it matches ichor-ui-service's own fixed name.
const ichorUIMetricsMonitorName = "ichor-ui-metrics-monitor"

// grafanaDashboardConfigMapName is templates/grafana/dashboard-configmap.yaml's fixed name.
const grafanaDashboardConfigMapName = "ichor-grafana-dashboard"

// checkMonitoringOptionsOffByDefault guards the "off by default" half
// chart options -- prometheus.enabled, prometheus.rules.enabled and
// grafana.dashboards.enabled must each render nothing under the suite's default
// render, the same contract TestMetricsCertEnabled's own comment documents for
// metricsCert.enabled.
func checkMonitoringOptionsOffByDefault(t *testing.T, release string, docs []map[string]any) {
	t.Helper()

	for _, kind := range []string{"ServiceMonitor", "PrometheusRule"} {
		if got := findAll(docs, kind); len(got) != 0 {
			t.Errorf("helm template %s .: expected no %s by default (prometheus.enabled and "+
				"prometheus.rules.enabled both default false); got %d",
				release, kind, len(got))
		}
	}
	if got := find(docs, kindConfigMap, grafanaDashboardConfigMapName); got != nil {
		t.Errorf("helm template %s .: expected no ConfigMap named %q by default "+
			"(grafana.dashboards.enabled defaults false)", release, grafanaDashboardConfigMapName)
	}
}

// TestIchorUIMonitorVerifiesTLS guards: the ichor-ui ServiceMonitor verifies the serving
// certificate against ichor-ui-ca by default, and ichorUI.tls.caSecret redirects it.
func TestIchorUIMonitorVerifiesTLS(t *testing.T) {
	tlsOf := func(sets ...string) map[string]any {
		docs := renderChartWithValues(t, "ichor", append([]string{"prometheus.enabled=true"}, sets...)...)
		m := find(docs, "ServiceMonitor", ichorUIMetricsMonitorName)
		if m == nil {
			t.Fatalf("no ServiceMonitor %q", ichorUIMetricsMonitorName)
		}
		eps, _ := m["spec"].(map[string]any)["endpoints"].([]any)
		tc, _ := eps[0].(map[string]any)["tlsConfig"].(map[string]any)
		if tc["insecureSkipVerify"] != nil {
			t.Errorf("tlsConfig must verify, got insecureSkipVerify=%v", tc["insecureSkipVerify"])
		}
		return tc
	}
	tc := tlsOf()
	ca, _ := tc["ca"].(map[string]any)
	cm, _ := ca["configMap"].(map[string]any)
	if cm["name"] != "ichor-ui-ca" || cm["key"] != "ca.crt" {
		t.Errorf("default ca: want ConfigMap ichor-ui-ca/ca.crt, got %v", ca)
	}
	if tc["serverName"] != "ichor-ui-service.default.svc" {
		t.Errorf("serverName: got %v", tc["serverName"])
	}
	ca, _ = tlsOf("ichorUI.tls.caSecret=my-ca")["ca"].(map[string]any)
	sec, _ := ca["secret"].(map[string]any)
	if sec["name"] != "my-ca" || sec["key"] != "ca.crt" || ca["configMap"] != nil {
		t.Errorf("caSecret: got %v", ca)
	}
}

// TestMonitoringOptionsEnabled guards the "actually renders, and renders something
// usable" half's chart options: ichor-ui's own ServiceMonitor, the
// PrometheusRule's two alerts, and the Grafana dashboard ConfigMap's JSON payload.
func TestMonitoringOptionsEnabled(t *testing.T) {
	docs := renderChartWithValues(t, "ichor",
		"prometheus.enabled=true", "prometheus.rules.enabled=true", "grafana.dashboards.enabled=true")

	if find(docs, "ServiceMonitor", ichorUIMetricsMonitorName) == nil {
		t.Errorf("helm template ichor . --set prometheus.enabled=true: expected a ServiceMonitor "+
			"named %q for ichor-ui", ichorUIMetricsMonitorName)
	}

	const ruleName = "ichor-alert-rules"
	rule := find(docs, "PrometheusRule", ruleName)
	if rule == nil {
		t.Fatalf("helm template ichor . --set prometheus.rules.enabled=true: expected a "+
			"PrometheusRule named %q", ruleName)
	}
	wantAlerts := map[string]bool{
		"IchorControllerDown": false, "IchorReconcileErrorsPersisting": false, "IchorCertificateExpiring": false,
	}
	spec, _ := rule["spec"].(map[string]any)
	groups, _ := spec["groups"].([]any)
	for _, g := range groups {
		gm, _ := g.(map[string]any)
		rules, _ := gm["rules"].([]any)
		for _, r := range rules {
			rm, _ := r.(map[string]any)
			if name, _ := rm["alert"].(string); name != "" {
				wantAlerts[name] = true
				if expr, _ := rm["expr"].(string); name == "IchorCertificateExpiring" &&
					expr != "ichor_certificate_expiry_timestamp_seconds - time() < 90 * 86400" {
					t.Errorf("IchorCertificateExpiring expr = %q, want the CA expiry metric against 90 days", expr)
				}
			}
		}
	}
	for name, found := range wantAlerts {
		if !found {
			t.Errorf("PrometheusRule %q: expected an alert named %q", ruleName, name)
		}
	}

	cm := find(docs, kindConfigMap, grafanaDashboardConfigMapName)
	if cm == nil {
		t.Fatalf("helm template ichor . --set grafana.dashboards.enabled=true: expected a ConfigMap "+
			"named %q", grafanaDashboardConfigMapName)
	}
	data, _ := cm["data"].(map[string]any)
	raw, _ := data["ichor-overview.json"].(string)
	var dashboard struct {
		Panels []any `json:"panels"`
	}
	if err := json.Unmarshal([]byte(raw), &dashboard); err != nil {
		t.Fatalf("ConfigMap %q's ichor-overview.json is not valid JSON: %v", grafanaDashboardConfigMapName, err)
	}
	if len(dashboard.Panels) == 0 {
		t.Errorf("ConfigMap %q's ichor-overview.json has no panels", grafanaDashboardConfigMapName)
	}
}

// renderChart runs "helm template" against the chart in this directory and
// decodes every rendered object into a generic map.
func renderChart(t *testing.T, release string) []map[string]any {
	t.Helper()
	return renderChartWithValues(t, release)
}

// renderChartWithValues is renderChart plus --set overrides, for invariants that only apply
// once a feature flag is on: metricsCert.enabled's metrics Secret and the ServiceMonitor TLS
// config referencing it don't exist at all under the suite's default (flags-off) render.
func renderChartWithValues(t *testing.T, release string, sets ...string) []map[string]any {
	t.Helper()

	args := make([]string, 0, 3+2*len(sets))
	args = append(args, "template", release, ".")
	for _, s := range sets {
		args = append(args, "--set", s)
	}

	out, err := exec.Command("helm", args...).CombinedOutput()
	if err != nil {
		t.Fatalf("helm %s: %v\n%s", strings.Join(args, " "), err, out)
	}

	label := "helm " + strings.Join(args, " ") + " output"
	docs := decodeYAMLDocs(t, out, label)
	if len(docs) == 0 {
		t.Fatalf("helm %s produced no documents", strings.Join(args, " "))
	}
	return docs
}

// renderChartWithValuesErr runs "helm template" with --set overrides and returns its error
// instead of failing, for values the chart must refuse.
func renderChartWithValuesErr(release string, sets ...string) ([]byte, error) {
	args := make([]string, 0, 3+2*len(sets))
	args = append(args, "template", release, ".")

	for _, s := range sets {
		args = append(args, "--set", s)
	}

	return exec.Command("helm", args...).CombinedOutput()
}

// decodeYAMLDocs decodes every "---"-separated document in data into a generic map,
// skipping empty documents. label is only used in failure messages.
func decodeYAMLDocs(t *testing.T, data []byte, label string) []map[string]any {
	t.Helper()

	var docs []map[string]any
	dec := k8syaml.NewYAMLOrJSONDecoder(bytes.NewReader(data), 4096)
	for {
		var doc map[string]any
		if err := dec.Decode(&doc); err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			t.Fatalf("decoding %s: %v", label, err)
		}
		if doc != nil {
			docs = append(docs, doc)
		}
	}
	return docs
}

// loadYAMLDocs reads and decodes every document in a static YAML file on disk (as
// opposed to renderChart's "helm template" output).
func loadYAMLDocs(t *testing.T, path string) []map[string]any {
	t.Helper()

	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("reading %s: %v", path, err)
	}
	return decodeYAMLDocs(t, data, path)
}

func kindOf(doc map[string]any) string {
	k, _ := doc["kind"].(string)
	return k
}

func nameOf(doc map[string]any) string {
	md, _ := doc["metadata"].(map[string]any)
	n, _ := md["name"].(string)
	return n
}

func findAll(docs []map[string]any, kind string) []map[string]any {
	out := make([]map[string]any, 0, len(docs))
	for _, d := range docs {
		if kindOf(d) == kind {
			out = append(out, d)
		}
	}
	return out
}

func find(docs []map[string]any, kind, name string) map[string]any {
	for _, d := range findAll(docs, kind) {
		if nameOf(d) == name {
			return d
		}
	}
	return nil
}

// containsStr reports whether v, a decoded YAML sequence, contains want.
func containsStr(v any, want string) bool {
	list, _ := v.([]any)
	for _, item := range list {
		if s, _ := item.(string); s == want {
			return true
		}
	}
	return false
}

// checkFixedNames guards the three resource names cmd/main.go's cert rotator
// hardcodes: they must survive unchanged under any release name.
func checkFixedNames(t *testing.T, release string, docs []map[string]any) {
	t.Helper()

	fixed := []struct{ kind, name string }{
		{kindService, webhookServiceName},
		{kindValidatingWebhookConfiguration, webhookConfigName},
		{kindSecret, certSecretName},
	}
	for _, f := range fixed {
		if find(docs, f.kind, f.name) == nil {
			t.Errorf(
				"helm template %s .: expected a %s named %q (fixed, not release-templated, "+
					"because cmd/main.go's cert rotator hardcodes it); not found",
				release, f.kind, f.name,
			)
		}
	}
}

// checkWebhookInvariants guards's fail-closed decision: both
// webhooks must keep failurePolicy: Fail and match DELETE only.
func checkWebhookInvariants(t *testing.T, release string, docs []map[string]any) {
	t.Helper()

	wh := find(docs, kindValidatingWebhookConfiguration, webhookConfigName)
	if wh == nil {
		t.Fatalf(
			"helm template %s .: expected a %s named %q to check failurePolicy/operations against",
			release, kindValidatingWebhookConfiguration, webhookConfigName,
		)
	}

	webhooks, _ := wh["webhooks"].([]any)
	if len(webhooks) == 0 {
		t.Fatalf("helm template %s .: expected %q to carry at least one webhook entry",
			release, webhookConfigName)
	}

	for _, w := range webhooks {
		wm, _ := w.(map[string]any)
		name, _ := wm["name"].(string)

		if fp, _ := wm["failurePolicy"].(string); fp != "Fail" {
			t.Errorf(
				"webhook %q: expected failurePolicy: Fail (a down webhook "+
					"blocks Ichor CR deletes instead of letting them through); got %q",
				name, fp,
			)
		}

		rules, _ := wm["rules"].([]any)
		for _, r := range rules {
			rm, _ := r.(map[string]any)
			ops, _ := rm["operations"].([]any)
			// Widened these from DELETE-only: the approval cap
			// needs CREATE/UPDATE on TalosMachine, the schedulable check
			// UPDATE on TalosCluster. Anything else would be a new decision.
			want := map[string][]any{
				"vtalosmachine-v1alpha1.kb.io":           {opCreate, opUpdate, opDelete},
				"vmachinereclaim-v1alpha1.kb.io":         {opCreate, opUpdate},
				"vtaloscredentialrequest-v1alpha1.kb.io": {opCreate},
				// A patch is dry-rendered against the machines it selects.
				"vtalosconfigpatch-v1alpha1.kb.io":  {opCreate, opUpdate},
				"vichorinstallation-v1alpha1.kb.io": {opCreate, opUpdate, "DELETE"},
				"vtaloscluster-v1alpha1.kb.io":      {opCreate, opUpdate, opDelete},
				// Break-glass checks writes to existing CRs only.
				"vbreakglass-v1alpha1.kb.io": {opUpdate},
				// And the creation of a node reset by hand.
				"vbreakglassop-v1alpha1.kb.io": {"CREATE", "UPDATE"},
				// A change to spec.authentication, on create and update: and the
				// delete of a tracked cluster.
				"vauthentication-v1alpha1.kb.io": {opCreate, opUpdate},
				"vsecretrefs-v1alpha1.kb.io":     {opCreate, opUpdate},
			}[name]
			if !reflect.DeepEqual(ops, want) {
				t.Errorf("webhook %q: expected operations %v; got %v",
					name, want, ops)
			}
		}
	}
}

// checkKubeProxySwitchPolicy guards's kube-proxy-switch guard: the
// chart must install both the ValidatingAdmissionPolicy and its Binding --
// a Policy without a Binding enforces nothing, and a Binding naming a
// Policy that doesn't exist is equally inert, so neither half alone is a
// working guard. It also checks the Binding actually points at the Policy
// this chart ships, not a stale or mistyped name.
func checkKubeProxySwitchPolicy(t *testing.T, release string, docs []map[string]any) {
	t.Helper()

	policy := find(docs, kindValidatingAdmissionPolicy, kubeProxySwitchPolicyName)
	if policy == nil {
		t.Errorf(
			"helm template %s .: expected a %s named %q (kube-proxy-switch guard); not found",
			release, kindValidatingAdmissionPolicy, kubeProxySwitchPolicyName,
		)
	}

	binding := find(docs, kindValidatingAdmissionPolicyBind, kubeProxySwitchBindingName)
	if binding == nil {
		t.Errorf(
			"helm template %s .: expected a %s named %q (kube-proxy-switch guard); not found",
			release, kindValidatingAdmissionPolicyBind, kubeProxySwitchBindingName,
		)
	}

	if binding != nil {
		spec, _ := binding["spec"].(map[string]any)
		policyName, _ := spec["policyName"].(string)
		if policyName != kubeProxySwitchPolicyName {
			t.Errorf(
				"helm template %s .: %s %q has spec.policyName %q, want %q; "+
					"a binding to the wrong policy name enforces nothing",
				release, kindValidatingAdmissionPolicyBind, kubeProxySwitchBindingName, policyName,
				kubeProxySwitchPolicyName,
			)
		}
	}
}

// checkUIBackendRBACIsSeparate guards architecture.md "Trust": "only the controller
// holds an os:admin-equivalent Talos identity[;] the UI backend holds a read-only one."
// Collapsing the two -- the UI Deployment running as the controller's own
// ServiceAccount, or the UI's ClusterRole merged into manager-role -- would erase that
// boundary with no other signal, since both would still "work". Checks the whole chain:
// ichor-ui's Deployment runs as its own ServiceAccount, that ServiceAccount is bound only
// to ichor-ui's own ClusterRole, and at least one other ServiceAccount/ClusterRoleBinding
// pair exists (the controller's) that names neither.
func checkUIBackendRBACIsSeparate(t *testing.T, release string, docs []map[string]any) {
	t.Helper()

	uiDeployment := find(docs, kindDeployment, ichorUIDeploymentName)
	if uiDeployment == nil {
		t.Fatalf("helm template %s .: expected a %s named %q",
			release, kindDeployment, ichorUIDeploymentName)
	}
	if sa := deploymentServiceAccountName(uiDeployment); sa != ichorUIServiceAccountName {
		t.Errorf(
			"helm template %s .: %s %q runs as ServiceAccount %q, want %q (its own identity, "+
				"separate from the controller's)",
			release, kindDeployment, ichorUIDeploymentName, sa, ichorUIServiceAccountName,
		)
	}

	if find(docs, kindServiceAccount, ichorUIServiceAccountName) == nil {
		t.Fatalf("helm template %s .: expected a %s named %q",
			release, kindServiceAccount, ichorUIServiceAccountName)
	}
	if find(docs, kindClusterRole, ichorUIRoleName) == nil {
		t.Fatalf("helm template %s .: expected a %s named %q",
			release, kindClusterRole, ichorUIRoleName)
	}

	binding := find(docs, kindClusterRoleBinding, ichorUIRoleBindingName)
	if binding == nil {
		t.Fatalf("helm template %s .: expected a %s named %q",
			release, kindClusterRoleBinding, ichorUIRoleBindingName)
	}
	roleRef, subject := clusterRoleBindingRefs(binding)
	if roleRef != ichorUIRoleName || subject != ichorUIServiceAccountName {
		t.Errorf(
			"helm template %s .: %s %q binds ClusterRole %q to ServiceAccount %q, want %q to %q",
			release, kindClusterRoleBinding, ichorUIRoleBindingName, roleRef, subject,
			ichorUIRoleName, ichorUIServiceAccountName,
		)
	}

	// At least one other ClusterRoleBinding must exist (the controller's own) whose
	// ClusterRole and ServiceAccount are neither of ichor-ui's -- otherwise the two
	// identities could have silently become the same one.
	foundDistinctOther := false
	for _, b := range findAll(docs, kindClusterRoleBinding) {
		if nameOf(b) == ichorUIRoleBindingName {
			continue
		}
		roleRef, subject := clusterRoleBindingRefs(b)
		if roleRef != ichorUIRoleName && subject != ichorUIServiceAccountName {
			foundDistinctOther = true
			break
		}
	}
	if !foundDistinctOther {
		t.Errorf(
			"helm template %s .: expected at least one other %s (the controller's own) binding "+
				"neither ClusterRole %q nor ServiceAccount %q; the controller and the UI backend "+
				"must keep separate identities",
			release, kindClusterRoleBinding, ichorUIRoleName, ichorUIServiceAccountName,
		)
	}
}

// TestReclaimerRoleName pins the installed name of the reclaimer ClusterRole: the webhook refusal
// and docs/guides/adopt-and-reclaim.md tell users to bind ichor-machine-reclaimer. The chart renders
// it under the release's resource-name helper, so release "ichor" gives that name.
func TestReclaimerRoleName(t *testing.T) {
	on := renderChartWithValues(t, "ichor", "rbac.helpers.enabled=true")
	if find(on, kindClusterRole, "ichor-machine-reclaimer") == nil {
		t.Errorf("rbac.helpers.enabled with release ichor: want ClusterRole ichor-machine-reclaimer")
	}

	off := renderChartWithValues(t, "ichor")
	if find(off, kindClusterRole, "ichor-machine-reclaimer") != nil {
		t.Errorf("ClusterRole ichor-machine-reclaimer rendered without rbac.helpers.enabled")
	}
}

// TestReclaimEnabledIsIgnored pins: the removed reclaim.enabled value changes nothing in
// the manager or ichor-ui, and no flag or env var for it is rendered.
func TestReclaimEnabledIsIgnored(t *testing.T) {
	for _, docs := range [][]map[string]any{
		renderChartWithValues(t, "ichor", "reclaim.enabled=true", "rbac.helpers.enabled=true"),
	} {
		for _, d := range docs {
			if s := fmt.Sprint(d); strings.Contains(s, "--reclaim") || strings.Contains(s, "ICHOR_RECLAIM_ENABLED") {
				t.Errorf("%v: reclaim.enabled must be ignored", d["kind"])
			}
		}
	}
}

// TestUIOIDC pins: OIDC is off by default (no env, no impersonate grant), and when on the
// env reaches the container, the role equals the generated one including impersonate, and a
// narrowed impersonate list becomes resourceNames.
func TestUIOIDC(t *testing.T) {
	off := renderChartWithValues(t, "ichor")
	offDep := find(off, kindDeployment, ichorUIDeploymentName)
	if _, found := containerEnvValue(offDep, "ICHOR_OIDC_ISSUER"); found {
		t.Error("OIDC env present by default; it must be off")
	}

	base := []string{"ichorUI.oidc.enabled=true", "ichorUI.oidc.issuer=https://idp.example", "ichorUI.oidc.clientId=ichor"}
	withGroups := "ichorUI.oidc.impersonate.groups={oidc:platform}"
	withUsers := "ichorUI.oidc.impersonate.users={oidc:alice}"
	named := append(slices.Clone(base), withGroups, withUsers)

	on := renderChartWithValues(t, "ichor", named...)
	onDep := find(on, kindDeployment, ichorUIDeploymentName)
	if got, _ := containerEnvValue(onDep, "ICHOR_OIDC_ISSUER"); got != "https://idp.example" {
		t.Errorf("ICHOR_OIDC_ISSUER = %q", got)
	}
	checkUIBackendRBACMatchesConfig(t, "ichor", on, false)

	// Impersonation is by name only. The groups are the built-in ones plus the configured ones,
	// the users the configured ones; neither rule is ever without resourceNames.
	imp := impersonationRules(find(on, kindClusterRole, ichorUIRoleName))
	wantGroups := []string{"ichor:viewer", "ichor:operator", "ichor:admin", "oidc:platform"}
	if got := imp["groups"]; !slices.Equal(got, wantGroups) {
		t.Errorf("impersonated groups = %v", got)
	}
	if got := imp["users"]; !slices.Equal(got, []string{"oidc:alice"}) {
		t.Errorf("impersonated users = %v", got)
	}

	// Without the names, rendering fails rather than allowing every name.
	if out, err := renderChartWithValuesErr("ichor", append(slices.Clone(base), withUsers)...); err == nil {
		t.Errorf("OIDC rendered without impersonate.groups: %s", out)
	}
	if out, err := renderChartWithValuesErr("ichor", append(slices.Clone(base), withGroups)...); err == nil {
		t.Errorf("OIDC rendered without impersonate.users or anyUser: %s", out)
	}

	// anyUser is the explicit opt-out for users only; groups stay named.
	open := append(slices.Clone(base), withGroups, "ichorUI.oidc.impersonate.anyUser=true")
	anyUser := renderChartWithValues(t, "ichor", open...)
	rules, _ := find(anyUser, kindClusterRole, ichorUIRoleName)["rules"].([]any)
	sawOpenUsers := false
	for _, r := range rules {
		rm, _ := r.(map[string]any)
		isUsers := containsStr(rm["resources"], "users") && slices.Contains(stringsOf(rm["verbs"]), "impersonate")
		if isUsers && rm["resourceNames"] == nil {
			sawOpenUsers = true
		}
		if containsStr(rm["resources"], "groups") && rm["resourceNames"] == nil {
			t.Error("a groups rule without resourceNames renders")
		}
	}
	if !sawOpenUsers {
		t.Error("anyUser=true did not render the open users rule")
	}
}

// impersonationRules returns the resourceNames of the impersonate rule of each resource ("users", "groups")
// in a decoded ClusterRole, and fails the test on a rule that has none.
func impersonationRules(role map[string]any) map[string][]string {
	out := map[string][]string{}
	rules, _ := role["rules"].([]any)
	for _, r := range rules {
		rm, _ := r.(map[string]any)
		if !slices.Contains(stringsOf(rm["verbs"]), "impersonate") {
			continue
		}
		for _, res := range stringsOf(rm["resources"]) {
			out[res] = append(out[res], stringsOf(rm["resourceNames"])...)
		}
	}
	return out
}

// TestUIUsers pins's chart switch: off renders nothing of it; on renders the flags, the
// internal port, the volumes, the credentials Secret, the narrowed impersonate groups and the
// Role rules, and refuses to render without an external URL.
func TestUIUsers(t *testing.T) {
	off := renderChartWithValues(t, "ichor")
	if find(off, "Secret", "ichor-user-credentials") != nil {
		t.Error("the credentials Secret renders by default")
	}

	offDep := fmt.Sprint(find(off, kindDeployment, ichorUIDeploymentName)["spec"])
	if strings.Contains(offDep, "users-enabled") || strings.Contains(offDep, "oidc-signing") {
		t.Error("users flags or volumes render by default")
	}

	const url = "https://ichor.example.com"

	on := renderChartWithValues(t, "ichor", "ichorUI.users.enabled=true", "ichorUI.users.externalURL="+url)
	dep := fmt.Sprint(find(on, kindDeployment, ichorUIDeploymentName)["spec"])

	wants := []string{
		"--users-enabled=true", "--external-url=" + url, "--internal-addr=:8444", "--token-ttl=5m",
		"--refresh-lifetime=12h", "ichor-oidc-signing", "ichor-oidc-tls", "containerPort:8444",
	}

	for _, want := range wants {
		if !strings.Contains(dep, want) {
			t.Errorf("Deployment lacks %q: %s", want, dep)
		}
	}

	if strings.Contains(dep, "kube-api-server-url") || strings.Contains(dep, "kube-api-tls-server-name") {
		t.Errorf("kube API flags render by default: %s", dep)
	}

	withAPI := renderChartWithValues(t, "ichor", "ichorUI.users.enabled=true", "ichorUI.users.externalURL="+url,
		"ichorUI.users.kubeAPIServerURL=https://k8s.example.com:443", "ichorUI.users.kubeAPITLSServerName=kubernetes")
	apiDep := fmt.Sprint(find(withAPI, kindDeployment, ichorUIDeploymentName)["spec"])

	for _, want := range []string{
		"--kube-api-server-url=https://k8s.example.com:443",
		"--kube-api-tls-server-name=kubernetes",
	} {
		if !strings.Contains(apiDep, want) {
			t.Errorf("Deployment lacks %q: %s", want, apiDep)
		}
	}

	mgr := fmt.Sprint(findNameSuffix(on, kindDeployment, "controller-manager")["spec"])
	if !strings.Contains(mgr, "--user-issuer") || !strings.Contains(mgr, "--oidc-refresh-lifetime=12h") {
		t.Errorf("the manager does not get --user-issuer: %s", mgr)
	}

	if strings.Contains(fmt.Sprint(findNameSuffix(off, kindDeployment, "controller-manager")["spec"]), "--user-issuer") {
		t.Error("the manager gets --user-issuer by default")
	}

	if find(on, "Secret", "ichor-user-credentials") == nil {
		t.Error("the credentials Secret is not rendered")
	}

	svc := fmt.Sprint(find(on, "Service", "ichor-ui-service")["spec"])
	if !strings.Contains(svc, "port:8444") {
		t.Errorf("Service lacks the internal port: %s", svc)
	}

	role := fmt.Sprint(find(on, kindClusterRole, ichorUIRoleName)["rules"])
	for _, want := range []string{"ichor:viewer", "ichor:operator", "ichor:admin", "impersonate"} {
		if !strings.Contains(role, want) {
			t.Errorf("ClusterRole lacks %q: %s", want, role)
		}
	}

	checkUIBackendRBACMatchesConfig(t, "ichor", on, true)

	if _, err := renderChartWithValuesErr("ichor", "ichorUI.users.enabled=true"); err == nil {
		t.Error("users.enabled rendered without an external URL")
	}

	both := renderChartWithValues(t, "ichor", "ichorUI.users.enabled=true", "ichorUI.users.externalURL=https://x",
		"ichorUI.oidc.enabled=true", "ichorUI.oidc.issuer=https://idp", "ichorUI.oidc.clientId=c",
		"ichorUI.oidc.impersonate.groups={oidc:platform}", "ichorUI.oidc.impersonate.users={oidc:alice}")
	got := impersonationRules(find(both, kindClusterRole, ichorUIRoleName))["groups"]
	if !slices.Contains(got, "oidc:platform") || !slices.Contains(got, "ichor:admin") {
		t.Errorf("with an external IdP too, the groups are the built-in ones plus the configured: %v", got)
	}

	// The Ichor users are listed by the controller in a role that renders empty; with users
	// off there is none.
	managed := find(on, kindClusterRole, "ichor-ui-impersonate")
	if managed == nil {
		t.Fatal("the controller-managed impersonation ClusterRole is not rendered with users.enabled")
	}
	if rules, _ := managed["rules"].([]any); len(rules) != 0 {
		t.Errorf("the managed impersonation role must start empty: %v", rules)
	}
	if find(on, "ClusterRoleBinding", "ichor-ui-impersonate") == nil {
		t.Error("the managed impersonation role is not bound")
	}
	if find(off, kindClusterRole, "ichor-ui-impersonate") != nil {
		t.Error("the managed impersonation role renders by default")
	}
	for res, names := range impersonationRules(find(on, kindClusterRole, ichorUIRoleName)) {
		if res == "users" {
			t.Errorf("users-only mode must not grant a static users impersonation: %v", names)
		}
	}
}

// containerEnvValue returns the value of env var name on the ichor-ui container of a decoded
// Deployment, and whether it is set.
func containerEnvValue(deployment map[string]any, name string) (string, bool) {
	spec, _ := deployment["spec"].(map[string]any)
	template, _ := spec["template"].(map[string]any)
	podSpec, _ := template["spec"].(map[string]any)
	containers, _ := podSpec["containers"].([]any)
	for _, c := range containers {
		cm, _ := c.(map[string]any)
		if cm["name"] != "ichor-ui" {
			continue
		}
		envs, _ := cm["env"].([]any)
		for _, e := range envs {
			em, _ := e.(map[string]any)
			if em["name"] == name {
				v, _ := em["value"].(string)
				return v, true
			}
		}
	}
	return "", false
}

// deploymentServiceAccountName reads spec.template.spec.serviceAccountName from a decoded
// Deployment.
func deploymentServiceAccountName(deployment map[string]any) string {
	spec, _ := deployment["spec"].(map[string]any)
	template, _ := spec["template"].(map[string]any)
	podSpec, _ := template["spec"].(map[string]any)
	sa, _ := podSpec["serviceAccountName"].(string)
	return sa
}

// clusterRoleBindingRefs reads a decoded ClusterRoleBinding's roleRef.name and its first
// subject's name.
func clusterRoleBindingRefs(binding map[string]any) (roleRef, subject string) {
	ref, _ := binding["roleRef"].(map[string]any)
	roleRef, _ = ref["name"].(string)

	subjects, _ := binding["subjects"].([]any)
	if len(subjects) > 0 {
		sm, _ := subjects[0].(map[string]any)
		subject, _ = sm["name"].(string)
	}
	return roleRef, subject
}

// checkUIBackendRBACMatchesConfig guards against dist/chart/templates/rbac/ichor-ui-role.yaml
// (hand-written, Helm template syntax) drifting from config/rbac/ichor-ui/role.yaml
// (generated by "make manifests-ichor-ui" from internal/uiapi/rbac_markers.go):
// the two must grant the exact same permission set even though nothing propagates one into
// the other automatically (unlike the CRDs checkCRDsMatchConfig guards -- the chart's
// template syntax means this has to be a comparison, not a sync). Compares rule sets, not
// YAML text or document order, so grouping resources/verbs into one apiGroups entry versus
// several is not a difference. Also checks the namespaced secrets Role the same way; see
// ichorUISecretsRoleName for why it can't be matched by name.
func checkUIBackendRBACMatchesConfig(t *testing.T, release string, docs []map[string]any, users bool) {
	t.Helper()

	configDocs := loadYAMLDocs(t, ichorUIConfigRolePath)
	configRole := find(configDocs, kindClusterRole, ichorUIRoleName)

	// The impersonate rules depend on the values (the configured groups and users)
	// and are pinned by TestUIOIDC and TestUIUsers; the rest of the role is compared whole.
	withoutImpersonate := func(role map[string]any) map[string]any {
		if role == nil {
			return nil
		}

		var kept []any

		rules, _ := role["rules"].([]any)
		for _, r := range rules {
			rm, _ := r.(map[string]any)
			if !slices.Contains(stringsOf(rm["verbs"]), "impersonate") {
				kept = append(kept, r)
			}
		}

		return map[string]any{"rules": kept}
	}

	checkRBACRulesMatch(t, release,
		"ClusterRole "+ichorUIRoleName,
		withoutImpersonate(configRole), withoutImpersonate(find(docs, kindClusterRole, ichorUIRoleName)),
		ichorUIConfigRolePath, "dist/chart/templates/rbac/ichor-ui-role.yaml")

	// The namespaced Role carrying the secrets rule: same name as the ClusterRole in
	// config/ (disambiguated only by kind there), but split into its own chart file
	// under ichorUISecretsRoleName -- matched here by kind/content, not name.
	// The Ichor users rules are in the generated role but rendered only with
	// ichorUI.users.enabled.
	configNS := find(configDocs, kindRole, ichorUIRoleName)
	if !users && configNS != nil {
		var kept []any
		rules, _ := configNS["rules"].([]any)
		for _, r := range rules {
			rm, _ := r.(map[string]any)
			if !containsStr(rm["resources"], "ichorusers") && !containsStr(rm["resourceNames"], "ichor-user-credentials") {
				kept = append(kept, r)
			}
		}
		configNS = map[string]any{"rules": kept}
	}
	checkRBACRulesMatch(t, release,
		"Role "+ichorUIRoleName+" (secrets)",
		configNS, find(docs, kindRole, ichorUISecretsRoleName),
		ichorUIConfigRolePath, "dist/chart/templates/rbac/ichor-ui-secrets-role.yaml")
}

// checkControllerRBACMatchesConfig is checkUIBackendRBACMatchesConfig for the controller:
// config/rbac/role.yaml's ClusterRole manager-role must equal the chart's manager-role
// template, and its namespaced Role manager-role (the secrets rules) must equal the chart's
// separate manager-secrets-role. The chart names are release-templated, hence the
// "-manager-role" / "-manager-secrets-role" suffix match.
//
// Deliberately not compared: leader-election-role (kubebuilder's static scaffold, not
// generated from markers), metrics-auth-role and metrics-reader (static scaffold), and the
// per-CRD admin/editor/viewer roles (generated per kind for end users, not the controller's
// own identity).
func checkControllerRBACMatchesConfig(t *testing.T, release string, docs []map[string]any) {
	t.Helper()

	configDocs := loadYAMLDocs(t, controllerConfigRolePath)

	checkRBACRulesMatch(t, release, "ClusterRole manager-role",
		find(configDocs, kindClusterRole, "manager-role"),
		findNameSuffix(docs, kindClusterRole, "-manager-role"),
		controllerConfigRolePath, "dist/chart/templates/rbac/manager-role.yaml")

	checkRBACRulesMatch(t, release, "Role manager-role (secrets)",
		find(configDocs, kindRole, "manager-role"),
		findNameSuffix(docs, kindRole, "-manager-secrets-role"),
		controllerConfigRolePath, "dist/chart/templates/rbac/manager-secrets-role.yaml")
}

const managerContainerName = "manager"

// TestManagerStartupProbe pins the startupProbe that covers the controller's start-up wait
// for the API server (cmd/waitapi.go, up to 5 minutes): without it the liveness probe kills
// the pod during a CA rotation.
func TestManagerStartupProbe(t *testing.T) {
	docs := renderChart(t, "ichor")
	spec, _ := findNameSuffix(docs, kindDeployment, "controller-manager")["spec"].(map[string]any)
	tmpl, _ := spec["template"].(map[string]any)
	podSpec, _ := tmpl["spec"].(map[string]any)
	containers, _ := podSpec["containers"].([]any)
	for _, c := range containers {
		container, _ := c.(map[string]any)
		if container["name"] != managerContainerName {
			continue
		}
		probe, _ := container["startupProbe"].(map[string]any)
		httpGet, _ := probe["httpGet"].(map[string]any)
		if httpGet["path"] != "/healthz" || fmt.Sprint(httpGet["port"]) != "8081" ||
			fmt.Sprint(probe["periodSeconds"]) != "10" || fmt.Sprint(probe["failureThreshold"]) != "36" {
			t.Fatalf("manager startupProbe = %v, want /healthz :8081 period 10 failureThreshold 36", probe)
		}
		return
	}
	t.Fatal("no manager container in the controller-manager Deployment")
}

// podTolerations returns a Deployment's pod tolerations.
func podTolerations(d map[string]any) []any {
	spec, _ := d["spec"].(map[string]any)
	tmpl, _ := spec["template"].(map[string]any)
	podSpec, _ := tmpl["spec"].(map[string]any)
	tols, _ := podSpec["tolerations"].([]any)

	return tols
}

// The controller must be able to run on a control plane: draining the only worker evicts it, and
// with the control plane tainted NoSchedule it could not come back to finish the upgrade it drives.
// The chart and the kustomize base (the installer manifest) carry the same toleration, ichor-ui included.
const keyOperator = "operator"

func TestManagerToleratesTheControlPlaneTaint(t *testing.T) {
	const exists = "Exists"

	want := []any{map[string]any{
		"key": "node-role.kubernetes.io/control-plane", keyOperator: exists, "effect": "NoSchedule",
	}}

	chart := podTolerations(findNameSuffix(renderChart(t, "ichor"), kindDeployment, "controller-manager"))
	if !reflect.DeepEqual(chart, want) {
		t.Errorf("chart manager tolerations = %v, want %v", chart, want)
	}

	var base map[string]any

	for _, d := range loadYAMLDocs(t, "../../config/manager/manager.yaml") {
		if d["kind"] == kindDeployment {
			base = d
		}
	}

	if got := podTolerations(base); !reflect.DeepEqual(got, want) {
		t.Errorf("config/manager tolerations = %v, want %v", got, want)
	}

	// ichor-ui too: a tainted-preset init waits for it before any worker is approved.
	if ui := podTolerations(findNameSuffix(renderChart(t, "ichor"), kindDeployment, "ichor-ui")); !reflect.DeepEqual(ui, want) {
		t.Errorf("ichor-ui tolerations = %v, want %v", ui, want)
	}
}

// findNameSuffix is find for release-templated names.
func findNameSuffix(docs []map[string]any, kind, suffix string) map[string]any {
	for _, d := range findAll(docs, kind) {
		if strings.HasSuffix(nameOf(d), suffix) {
			return d
		}
	}
	return nil
}

// checkRBACRulesMatch compares want and got's rules as a set of (apiGroup, resource, verb)
// triples, reporting any rule present in one but not the other with the exact file paths to
// fix. Grouping (which resources/verbs share one apiGroups entry) and ordering never matter.
func checkRBACRulesMatch(t *testing.T, release, label string, want, got map[string]any, wantPath, gotPath string) {
	t.Helper()

	if want == nil {
		t.Fatalf("helm template %s .: expected to find %s in %s; none found", release, label, wantPath)
	}
	if got == nil {
		t.Fatalf("helm template %s .: expected to find %s in the rendered chart (%s); none found",
			release, label, gotPath)
	}

	wantRules, _ := want["rules"].([]any)
	gotRules, _ := got["rules"].([]any)
	wantSet := rbacTriples(wantRules)
	gotSet := rbacTriples(gotRules)

	for triple := range wantSet {
		if !gotSet[triple] {
			t.Errorf("helm template %s .: %s is missing %s (present in %s); add it to %s",
				release, label, triple, wantPath, gotPath)
		}
	}
	for triple := range gotSet {
		if !wantSet[triple] {
			t.Errorf("helm template %s .: %s grants %s not present in %s; remove it from %s "+
				"or add it to %s if it's actually needed",
				release, label, triple, wantPath, gotPath, wantPath)
		}
	}
}

// rbacTriple is one (apiGroup, resource, verb) grant, the unit checkRBACRulesMatch compares
// rule sets by -- independent of how a role's author chose to group resources or verbs into
// apiGroups entries.
//
// names is the rule's resourceNames, comma-joined ("" = every name), so a name-scoped
// grant never hides a missing grant for another name.
type rbacTriple struct{ group, resource, verb, names string }

func (r rbacTriple) String() string {
	group := r.group
	if group == "" {
		group = "core"
	}
	s := group + "/" + r.resource + ":" + r.verb
	if r.names != "" {
		s += " [resourceNames " + r.names + "]"
	}
	return s
}

// rbacTriples expands a decoded ClusterRole/Role's rules into the full set of
// (apiGroup, resource, verb) grants they make.
func rbacTriples(rules []any) map[rbacTriple]bool {
	set := make(map[rbacTriple]bool)
	for _, r := range rules {
		rm, _ := r.(map[string]any)
		names := strings.Join(stringsOf(rm["resourceNames"]), ",")
		for _, g := range stringsOf(rm["apiGroups"]) {
			for _, res := range stringsOf(rm["resources"]) {
				for _, v := range stringsOf(rm["verbs"]) {
					set[rbacTriple{g, res, v, names}] = true
				}
			}
		}
	}
	return set
}

// stringsOf reads a decoded YAML sequence of strings, skipping any non-string entries.
func stringsOf(v any) []string {
	list, _ := v.([]any)
	out := make([]string, 0, len(list))
	for _, item := range list {
		if s, ok := item.(string); ok {
			out = append(out, s)
		}
	}
	return out
}

// checkNoCABundle guards the other half: no caBundle may be
// templated anywhere, or it would drift on every Argo CD sync.
func checkNoCABundle(t *testing.T, release string, docs []map[string]any) {
	t.Helper()

	for _, d := range docs {
		if walkHasKey(d, "caBundle") {
			t.Errorf(
				"helm template %s .: found a caBundle key in %s %q; the webhook "+
					"config with no caBundle (cert-controller injects it at runtime) so a templated "+
					"value here would drift on every Argo CD sync",
				release, kindOf(d), nameOf(d),
			)
		}
	}
}

func walkHasKey(v any, key string) bool {
	switch x := v.(type) {
	case map[string]any:
		if _, ok := x[key]; ok {
			return true
		}
		for _, vv := range x {
			if walkHasKey(vv, key) {
				return true
			}
		}
	case []any:
		for _, vv := range x {
			if walkHasKey(vv, key) {
				return true
			}
		}
	}
	return false
}

// checkCertSecretHasNoData guards the easy-to-get-backwards half's Secret: it must exist, and it must carry no data
// key, so
// cert-controller's Get succeeds and its own Update is what fills it in.
func checkCertSecretHasNoData(t *testing.T, release string, docs []map[string]any) {
	t.Helper()

	secret := find(docs, kindSecret, certSecretName)
	if secret == nil {
		t.Fatalf("helm template %s .: expected a %s named %q",
			release, kindSecret, certSecretName)
	}
	if data, ok := secret["data"]; ok {
		t.Errorf(
			"helm template %s .: %q has a data key; it must ship empty "+
				"(metadata only) so cert-controller's Get succeeds and its own Update fills it "+
				"in at runtime; got data=%v",
			release, certSecretName, data,
		)
	}
}

// checkSecretsRoleAndBinding guards the RBAC half of the two findings: the
// Helm plugin can only emit one kind for the name controller-gen gives both
// the ClusterRole and the Role it calls "manager-role", so the Secret rules
// need their own Role, hand-created because the plugin silently drops them.
func checkSecretsRoleAndBinding(t *testing.T, release string, docs []map[string]any) {
	t.Helper()

	role := findSecretsRole(docs)
	if role == nil {
		t.Fatalf(
			"helm template %s .: expected a Role carrying get/patch/update on %q (restricted by "+
				"resourceNames) plus create/list/watch on secrets; the Helm plugin can only emit "+
				"one kind for controller-gen's shared \"manager-role\" name and silently drops this "+
				"rule set",
			release, certSecretName,
		)
	}

	roleName := nameOf(role)
	binding := findRoleBindingTo(docs, roleName)
	if binding == nil {
		t.Fatalf("helm template %s .: expected a %s pointing at Role %q; none found",
			release, kindRoleBinding, roleName)
	}
	if find(docs, kindRole, roleName) == nil {
		t.Errorf(
			"helm template %s .: %s %q references Role %q, but no %s with that name was "+
				"rendered",
			release, kindRoleBinding, nameOf(binding), roleName, kindRole,
		)
	}
}

func findSecretsRole(docs []map[string]any) map[string]any {
	for _, role := range findAll(docs, kindRole) {
		rules, _ := role["rules"].([]any)
		if hasCreateListWatchSecrets(rules) && hasCertResourceNameRule(rules) {
			return role
		}
	}
	return nil
}

func hasCreateListWatchSecrets(rules []any) bool {
	for _, r := range rules {
		rm, _ := r.(map[string]any)
		if _, hasNames := rm["resourceNames"]; hasNames {
			continue
		}
		if containsStr(rm["resources"], "secrets") &&
			containsStr(rm["verbs"], "create") &&
			containsStr(rm["verbs"], "list") &&
			containsStr(rm["verbs"], "watch") {
			return true
		}
	}
	return false
}

func hasCertResourceNameRule(rules []any) bool {
	for _, r := range rules {
		rm, _ := r.(map[string]any)
		if !containsStr(rm["resourceNames"], certSecretName) {
			continue
		}
		if containsStr(rm["verbs"], "get") &&
			containsStr(rm["verbs"], "patch") &&
			containsStr(rm["verbs"], "update") {
			return true
		}
	}
	return false
}

func findRoleBindingTo(docs []map[string]any, roleName string) map[string]any {
	for _, rb := range findAll(docs, kindRoleBinding) {
		ref, _ := rb["roleRef"].(map[string]any)
		kind, _ := ref["kind"].(string)
		name, _ := ref["name"].(string)
		if kind == kindRole && name == roleName {
			return rb
		}
	}
	return nil
}

// checkNoClusterWideSecretsRead guards the regression
// (commit 645f5be reintroduced a ClusterRole rule granting unrestricted
// get/list/watch on every Secret in every namespace, which 823b04f had
// already removed once): no ClusterRole in the rendered chart may grant
// get, list or watch on secrets without resourceNames to restrict it. The
// toggled manager-role template renders as a Role instead of a ClusterRole
// under rbac.namespaced: true, but the default (false, checked here) is
// exactly the case that regressed.
func checkNoClusterWideSecretsRead(t *testing.T, release string, docs []map[string]any) {
	t.Helper()

	for _, cr := range findAll(docs, kindClusterRole) {
		rules, _ := cr["rules"].([]any)
		for _, r := range rules {
			rm, _ := r.(map[string]any)
			if _, hasNames := rm["resourceNames"]; hasNames {
				continue
			}

			if !containsStr(rm["resources"], "secrets") {
				continue
			}

			if containsStr(rm["verbs"], "get") || containsStr(rm["verbs"], "list") || containsStr(rm["verbs"], "watch") {
				t.Errorf(
					"helm template %s .: ClusterRole %q grants %v on secrets across every namespace with no "+
						"resourceNames; the bundle Secret is resolved in the controller's own namespace"+
						", so this permission must live in a namespace-scoped Role instead",
					release, nameOf(cr), rm["verbs"],
				)
			}
		}
	}
}

// checkCRDsMatchConfig guards against the drift that shipped a
// TalosConfigPatch CRD chart users could not use typed configuration with:
// every CRD generated into config/crd/bases/ must appear in the rendered
// chart with an equivalent schema. It compares parsed objects, not raw text,
// so the chart's "{{- if .Values.crd.enabled }}" wrapper and reindentation
// never cause a false failure.
func checkCRDsMatchConfig(t *testing.T, release string, docs []map[string]any) {
	t.Helper()

	entries, err := os.ReadDir(crdSourceDir)
	if err != nil {
		t.Fatalf("reading %s: %v", crdSourceDir, err)
	}

	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".yaml") {
			continue
		}
		path := filepath.Join(crdSourceDir, entry.Name())

		data, err := os.ReadFile(path)
		if err != nil {
			t.Fatalf("reading %s: %v", path, err)
		}
		var want map[string]any
		if err := k8syaml.NewYAMLOrJSONDecoder(bytes.NewReader(data), 4096).Decode(&want); err != nil {
			t.Fatalf("decoding %s: %v", path, err)
		}

		name := nameOf(want)
		got := find(docs, kindCustomResourceDefinition, name)
		if got == nil {
			t.Fatalf("%s", crdDriftMsg(release, name, path, "is missing from the chart entirely"))
			continue
		}

		for _, detail := range diffCRDSchemas(want, got) {
			t.Errorf("%s", crdDriftMsg(release, name, path, detail))
		}
	}
}

// crdDriftMsg builds the failure message checkCRDsMatchConfig reports: it
// names the CRD and the detail, says dist/chart is generated from config/
// and the fix is to re-sync it, and points at CONTRIBUTING.md's chart
// warning.
func crdDriftMsg(release, name, sourcePath, detail string) string {
	return "helm template " + release + " .: CustomResourceDefinition " + name + " " + detail +
		"; dist/chart is generated from config/ (see CONTRIBUTING.md's chart warning) " +
		"and has drifted out of sync with " + sourcePath + "; re-sync it"
}

// diffCRDSchemas compares, for each version, the full schema and (for a
// more specific message) the set of top-level spec properties keys. It
// returns one detail string per mismatch found, or nil if the CRDs agree.
func diffCRDSchemas(want, got map[string]any) []string {
	var details []string

	wantVersions := crdVersions(want)
	gotVersions := crdVersions(got)

	for name, wantVersion := range wantVersions {
		gotVersion, ok := gotVersions[name]
		if !ok {
			details = append(details, "is missing version "+name+" in the chart")
			continue
		}

		wantSchema, _ := wantVersion["schema"].(map[string]any)
		gotSchema, _ := gotVersion["schema"].(map[string]any)
		if reflect.DeepEqual(wantSchema, gotSchema) {
			continue
		}

		wantKeys := specPropertyKeys(wantSchema)
		gotKeys := specPropertyKeys(gotSchema)
		if !reflect.DeepEqual(wantKeys, gotKeys) {
			details = append(details, "version "+name+"'s spec properties are "+
				strings.Join(gotKeys, ",")+" in the chart but "+strings.Join(wantKeys, ",")+
				" in config/crd/bases")
			continue
		}

		details = append(details, "version "+name+"'s schema differs from config/crd/bases "+
			"even though its top-level spec properties match")
	}

	return details
}

// crdVersions indexes a decoded CRD's spec.versions by version name.
func crdVersions(doc map[string]any) map[string]map[string]any {
	spec, _ := doc["spec"].(map[string]any)
	versions, _ := spec["versions"].([]any)

	out := make(map[string]map[string]any, len(versions))
	for _, v := range versions {
		vm, _ := v.(map[string]any)
		name, _ := vm["name"].(string)
		out[name] = vm
	}
	return out
}

// metricsCertSecretName is cmd/main.go's second cert-controller rotator's fixed Secret name --
// extras/metrics-server-cert.yaml must ship it under this exact name,
// and the ServiceMonitor's tlsConfig must reference this exact name back, or Prometheus
// Operator resolves a certificate that was never created.
const metricsCertSecretName = "ichor-metrics-server-cert"

// TestMetricsCertEnabled guards metricsCert.enabled=true, which renders nothing at all
// under TestChartInvariants's default-values render: the Secret cert-controller's second
// rotator writes into, and the ServiceMonitor's tlsConfig referencing it, must name the exact
// same Secret -- caught empirically once, by actually rendering with the flag on rather than
// reading the templates statically (the ServiceMonitor used to hardcode the unprefixed
// "metrics-server-cert" while the Secret shipped as "ichor-metrics-server-cert").
func TestMetricsCertEnabled(t *testing.T) {
	docs := renderChartWithValues(t, "ichor", "metricsCert.enabled=true", "prometheus.enabled=true")

	secret := find(docs, kindSecret, metricsCertSecretName)
	if secret == nil {
		t.Fatalf("helm template . --set metricsCert.enabled=true: expected a %s named %q",
			kindSecret, metricsCertSecretName)
	}
	if data, ok := secret["data"]; ok {
		t.Errorf("helm template . --set metricsCert.enabled=true: %q has a data key; cert-controller's "+
			"rotator has no Create path, only Update, so this must ship empty; got data=%v",
			metricsCertSecretName, data)
	}

	monitor := find(docs, "ServiceMonitor", "ichor-controller-manager-metrics-monitor")
	if monitor == nil {
		t.Fatalf("helm template . --set metricsCert.enabled=true,prometheus.enabled=true: " +
			"expected a ServiceMonitor named \"ichor-controller-manager-metrics-monitor\"")
	}
	const nameKey = "name"
	tlsConfigPath := []string{"spec", "endpoints", "0", "tlsConfig"}
	for _, suffix := range [][]string{
		{"ca", "secret", nameKey},
		{"cert", "secret", nameKey},
		{"keySecret", nameKey},
	} {
		path := append(append([]string{}, tlsConfigPath...), suffix...)
		got := walkPath(monitor, path)
		if got != metricsCertSecretName {
			t.Errorf("ServiceMonitor %s: want %q, got %q; it must name the same Secret "+
				"extras/metrics-server-cert.yaml ships (%q)",
				strings.Join(path, "."), metricsCertSecretName, got, metricsCertSecretName)
		}
	}
}

// walkPath descends a decoded document through nested maps and, for a numeric segment, a
// slice index, returning "" if any step doesn't match.
func walkPath(doc map[string]any, path []string) string {
	var cur any = doc
	for _, p := range path {
		switch v := cur.(type) {
		case map[string]any:
			cur = v[p]
		case []any:
			i, err := strconv.Atoi(p)
			if err != nil || i < 0 || i >= len(v) {
				return ""
			}
			cur = v[i]
		default:
			return ""
		}
	}
	s, _ := cur.(string)
	return s
}

// specPropertyKeys returns the sorted set of top-level spec.properties keys
// a CRD version's schema declares.
func specPropertyKeys(schema map[string]any) []string {
	openAPI, _ := schema["openAPIV3Schema"].(map[string]any)
	props, _ := openAPI["properties"].(map[string]any)
	specProp, _ := props["spec"].(map[string]any)
	specProps, _ := specProp["properties"].(map[string]any)

	keys := make([]string, 0, len(specProps))
	for k := range specProps {
		keys = append(keys, k)
	}
	slices.Sort(keys)
	return keys
}

// installerConfigRolePath is config/rbac/ichor-installer/role.yaml (hand-written):
// the installer Job's ClusterRole and namespaced Role, whose chart copy
// templates/rbac/ichor-installer.yaml checkInstallerRBAC compares as rule sets.
const installerConfigRolePath = "../../config/rbac/ichor-installer/role.yaml"

// TestInstallerRBAC pins the installer Job's identity: absent unless
// installer.enabled (a chart-installed Ichor is normally Argo CD's, and nothing should hold
// the cluster-role escalation the installer needs), present and equal to config/rbac/ichor-
// installer when enabled, and never able to touch a Secret.
func TestInstallerRBAC(t *testing.T) {
	t.Run("absent by default", func(t *testing.T) {
		docs := renderChartWithValues(t, "ichor")
		if find(docs, kindServiceAccount, "ichor-installer") != nil ||
			find(docs, kindClusterRole, "ichor-installer-role") != nil {
			t.Errorf("the installer's ServiceAccount/ClusterRole render by default; " +
				"they must need installer.enabled=true")
		}
	})

	t.Run("enabled matches config", func(t *testing.T) {
		docs := renderChartWithValues(t, "ichor", "installer.enabled=true")
		configDocs := loadYAMLDocs(t, installerConfigRolePath)

		if find(docs, kindServiceAccount, "ichor-installer") == nil {
			t.Fatalf("installer.enabled=true renders no ServiceAccount ichor-installer, " +
				"the name the controller puts in the Job")
		}

		clusterRole := find(docs, kindClusterRole, "ichor-installer-role")
		role := find(docs, kindRole, "ichor-installer-role")

		// The chart scopes the namespaces rule to the release namespace; config says ichor-system.
		for _, d := range []map[string]any{clusterRole, role} {
			rules, _ := d["rules"].([]any)
			for _, r := range rules {
				rm, _ := r.(map[string]any)
				if names, ok := rm["resourceNames"].([]any); ok && len(names) == 1 && names[0] == "default" {
					rm["resourceNames"] = []any{"ichor-system"}
				}
			}
		}

		checkRBACRulesMatch(t, "ichor", "ClusterRole installer-role",
			find(configDocs, kindClusterRole, "installer-role"), clusterRole,
			installerConfigRolePath, "dist/chart/templates/rbac/ichor-installer.yaml")
		checkRBACRulesMatch(t, "ichor", "Role installer-role",
			find(configDocs, kindRole, "installer-role"), role,
			installerConfigRolePath, "dist/chart/templates/rbac/ichor-installer.yaml")

		checkInstallerCoversEveryCRD(t, clusterRole)
		checkInstallerCoversEveryCRD(t, find(configDocs, kindClusterRole, "installer-role"))

		// Snapshot garbage collection (non-fatal in the installer, but it should work).
		if !rbacTriples(allRules(role))[rbacTriple{"", "configmaps", "delete", ""}] {
			t.Errorf("the installer Role cannot delete configmaps, so snapshot GC fails")
		}

		for triple := range rbacTriples(append(allRules(clusterRole), allRules(role)...)) {
			if triple.resource == "secrets" || triple.resource == "*" || triple.verb == "*" {
				t.Errorf("the installer is granted %s; it must never read or write a Secret "+
					"or hold a wildcard", triple)
			}
		}
	})
}

const (
	verbCreateController = "create"
	verbGetController    = "get"
)

// TestControllerRBACHoldsNoEscalation pins that the controller's own ClusterRole holds none of the
// escalation, CRD or workload rights that the one-shot Jobs (installer, Cilium) exist to keep away
// from it.
func TestControllerRBACHoldsNoEscalation(t *testing.T) {
	docs := renderChart(t, "ichor")

	for _, d := range findAll(docs, kindClusterRole) {
		if !strings.HasSuffix(nameOf(d), "-manager-role") {
			continue
		}

		for triple := range rbacTriples(allRules(d)) {
			// The one exception: the controller keeps the list of Ichor users that ichor-ui may
			// impersonate in one named ClusterRole, and needs `escalate` on that role alone to grant the
			// impersonate right it does not hold. Only the exact name qualifies.
			managed := triple.group == "rbac.authorization.k8s.io" && triple.resource == resClusterRoles &&
				triple.names == "ichor-ui-impersonate"
			if managed && (triple.verb == "escalate" || triple.verb == verbGetController || triple.verb == "update") {
				continue
			}

			switch {
			case triple.verb == "escalate" || triple.verb == "bind",
				triple.resource == "customresourcedefinitions" && triple.verb != verbGetController,
				triple.resource == "clusterroles", triple.resource == "clusterrolebindings",
				triple.resource == "deployments" && triple.verb == verbCreateController:
				t.Errorf("the controller holds %s; the one-shot Jobs apply cluster-wide objects, not the controller", triple)
			}
		}
	}
}

// checkInstallerCoversEveryCRD fails when a CRD in config/crd/bases is missing from the
// installer ClusterRole's patch/update resourceNames: server-side apply of that CRD is then
// Forbidden and the whole upgrade rolls back (ichorusers, found on the demo).
func checkInstallerCoversEveryCRD(t *testing.T, clusterRole map[string]any) {
	t.Helper()

	if clusterRole == nil {
		t.Fatal("no installer ClusterRole to check")
	}

	entries, err := os.ReadDir(crdSourceDir)
	if err != nil {
		t.Fatalf("reading %s: %v", crdSourceDir, err)
	}

	triples := rbacTriples(allRules(clusterRole))

	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".yaml") {
			continue
		}

		var crd map[string]any
		path := filepath.Join(crdSourceDir, entry.Name())

		data, err := os.ReadFile(path)
		if err != nil {
			t.Fatalf("reading %s: %v", path, err)
		}

		if err := k8syaml.NewYAMLOrJSONDecoder(bytes.NewReader(data), 4096).Decode(&crd); err != nil {
			t.Fatalf("decoding %s: %v", path, err)
		}

		name := nameOf(crd)

		for _, verb := range []string{"patch", "update"} {
			covered := false

			for tr := range triples {
				if tr.group == "apiextensions.k8s.io" && tr.resource == "customresourcedefinitions" && tr.verb == verb &&
					slices.Contains(strings.Split(tr.names, ","), name) {
					covered = true
				}
			}

			if !covered {
				t.Errorf("the installer ClusterRole cannot %s CRD %s (add it to the resourceNames of the "+
					"patch/update rule in config/rbac/ichor-installer/role.yaml and the chart template)",
					verb, name)
			}
		}
	}
}

// TestPodNamespaceFromDownwardAPI pins POD_NAMESPACE on both the manager and ichor-ui
// containers to the downward API: ichor-ui resolves the secrets bundle in
// it, and an empty value fails every machine page with "controller namespace is empty".
func TestPodNamespaceFromDownwardAPI(t *testing.T) {
	seen := map[string]bool{}
	for _, d := range findAll(renderChartWithValues(t, "ichor"), kindDeployment) {
		spec, _ := d["spec"].(map[string]any)
		template, _ := spec["template"].(map[string]any)
		podSpec, _ := template["spec"].(map[string]any)
		containers, _ := podSpec["containers"].([]any)
		for _, c := range containers {
			cm, _ := c.(map[string]any)
			name, _ := cm["name"].(string)
			if name != "manager" && name != ichorUIDeploymentName {
				continue
			}
			seen[name] = true
			if got := envFieldPath(cm, "POD_NAMESPACE"); got != "metadata.namespace" {
				t.Errorf("%s container: POD_NAMESPACE fieldRef = %q, want metadata.namespace", name, got)
			}
		}
	}
	for _, name := range []string{"manager", ichorUIDeploymentName} {
		if !seen[name] {
			t.Errorf("no %q container rendered", name)
		}
	}
}

// envFieldPath returns the downward-API fieldPath of env var name on a decoded container.
func envFieldPath(container map[string]any, name string) string {
	envs, _ := container["env"].([]any)
	for _, e := range envs {
		em, _ := e.(map[string]any)
		if em["name"] != name {
			continue
		}
		from, _ := em["valueFrom"].(map[string]any)
		ref, _ := from["fieldRef"].(map[string]any)
		p, _ := ref["fieldPath"].(string)

		return p
	}

	return ""
}

func allRules(doc map[string]any) []any {
	rules, _ := doc["rules"].([]any)

	return rules
}

// TestUICredentialsDownloadVerb guards: the download verb on talosclusters/credentials is
// granted to nobody by default, not to ichor-ui-role, and only bound when the values say so.
func TestUICredentialsDownloadVerb(t *testing.T) {
	const roleName = "ichor-credentials-role"

	bindingsTo := func(docs []map[string]any) []map[string]any {
		var out []map[string]any
		for _, b := range findAll(docs, kindClusterRoleBinding) {
			if ref, _ := clusterRoleBindingRefs(b); ref == roleName {
				out = append(out, b)
			}
		}
		return out
	}

	off := renderChartWithValues(t, "ichor")
	if find(off, kindClusterRole, roleName) != nil {
		t.Errorf("ClusterRole %q rendered by default; it is a helper role (rbac.helpers.enabled)", roleName)
	}
	const subresource = "talosclusters/credentials"

	ui := find(off, kindClusterRole, ichorUIRoleName)
	if ui == nil || strings.Contains(fmt.Sprint(ui["rules"]), subresource) {
		t.Errorf("ichor-ui-role must not hold the credentials download verb")
	}

	helpers := renderChartWithValues(t, "ichor", "rbac.helpers.enabled=true")
	role := find(helpers, kindClusterRole, roleName)
	rules := fmt.Sprint(role["rules"])
	if role == nil || !strings.Contains(rules, subresource) || !strings.Contains(rules, "download") {
		t.Fatalf("expected ClusterRole %q granting download on talosclusters/credentials; got %v", roleName, role)
	}
	if b := bindingsTo(helpers); len(b) != 0 {
		t.Errorf("the credentials verb is bound by default: %v", b)
	}

	groups := renderChartWithValues(t, "ichor", "ichorUI.credentials.groups={oidc:platform-admins}")
	bs := bindingsTo(groups)
	if len(bs) != 1 || !strings.Contains(fmt.Sprint(bs[0]["subjects"]), "oidc:platform-admins") ||
		strings.Contains(fmt.Sprint(bs[0]["subjects"]), "ServiceAccount") {
		t.Errorf("ichorUI.credentials.groups must bind only those groups, got %v", bs)
	}
	if find(groups, kindClusterRole, roleName) == nil {
		t.Errorf("a bound credentials role must render without the helper roles")
	}

	sa := renderChartWithValues(t, "ichor", "ichorUI.credentials.serviceAccount=true")
	bs = bindingsTo(sa)
	if len(bs) != 1 || !strings.Contains(fmt.Sprint(bs[0]["subjects"]), ichorUIServiceAccountName) {
		t.Errorf("ichorUI.credentials.serviceAccount must bind the ichor-ui ServiceAccount, got %v", bs)
	}
}

// TestUIDiagnosticsDownloadVerb guards: the download verb on talosmachines'
// support-bundle, etcd-snapshot and packet-capture subresources is granted to nobody by
// default, not to the ichor-ui ServiceAccount's own role, and only bound when the values say so.
func TestUIDiagnosticsDownloadVerb(t *testing.T) {
	const roleName = "ichor-diagnostics-role"

	grants := func(role map[string]any) bool {
		return strings.Contains(fmt.Sprint(role["rules"]), "download")
	}

	bindingsTo := func(docs []map[string]any) []map[string]any {
		var out []map[string]any
		for _, b := range findAll(docs, kindClusterRoleBinding) {
			if ref, _ := clusterRoleBindingRefs(b); ref == roleName {
				out = append(out, b)
			}
		}
		return out
	}

	off := renderChartWithValues(t, "ichor")
	if find(off, kindClusterRole, roleName) != nil {
		t.Errorf("ClusterRole %q rendered by default; it is a helper role (rbac.helpers.enabled)", roleName)
	}

	helpers := renderChartWithValues(t, "ichor", "rbac.helpers.enabled=true")
	role := find(helpers, kindClusterRole, roleName)
	if role == nil || !grants(role) {
		t.Fatalf("expected ClusterRole %q granting the download verb; got %v", roleName, role)
	}
	for _, sub := range []string{
		"talosmachines/support-bundle", "talosmachines/etcd-snapshot", "talosmachines/packet-capture",
	} {
		if !strings.Contains(fmt.Sprint(role["rules"]), sub) {
			t.Errorf("ClusterRole %q lacks %s", roleName, sub)
		}
	}
	if b := bindingsTo(helpers); len(b) != 0 {
		t.Errorf("the download verb is bound by default: %v", b)
	}
	if ui := find(off, kindClusterRole, ichorUIRoleName); ui == nil || grants(ui) {
		t.Errorf("ichor-ui-role must not hold the download verb")
	}

	groups := renderChartWithValues(t, "ichor", "ichorUI.diagnostics.groups={oidc:platform-admins}")
	bs := bindingsTo(groups)
	if len(bs) != 1 || !strings.Contains(fmt.Sprint(bs[0]["subjects"]), "oidc:platform-admins") ||
		strings.Contains(fmt.Sprint(bs[0]["subjects"]), "ServiceAccount") {
		t.Errorf("ichorUI.diagnostics.groups must bind only those groups, got %v", bs)
	}

	sa := renderChartWithValues(t, "ichor", "ichorUI.diagnostics.serviceAccount=true")
	bs = bindingsTo(sa)
	if len(bs) != 1 || !strings.Contains(fmt.Sprint(bs[0]["subjects"]), ichorUIServiceAccountName) {
		t.Errorf("ichorUI.diagnostics.serviceAccount must bind the ichor-ui ServiceAccount, got %v", bs)
	}

	// The role is rendered, and bound, even when the RBAC helper roles are off.
	noHelpers := renderChartWithValues(t, "ichor", "ichorUI.diagnostics.groups={oidc:platform-admins}")
	if find(noHelpers, kindClusterRole, roleName) == nil || len(bindingsTo(noHelpers)) != 1 {
		t.Errorf("a bound diagnostics role must render without the helper roles")
	}
}

const resClusterRoles = "clusterroles"
